var EBikeButtonAktiviert, EBikePVAktiviert, SmartPlugEBike;


// Deklaration
createState('0_userdata.0.SmartPlugs.SmarPlug_EBike', true, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "SmartPlug_EBike","role": "","type": "boolean","desc": "Blockly erzeugt","read": true,"write": true,"def": false}'), async () => {
});
createState('0_userdata.0.SmartPlugs.SmartPlug_EBike_Timeout', 0, ((common) => typeof common !== 'object' ? JSON.parse(common) : common)('{"name": "SmartPlug_EBike_Timeout","role": "","type": "number","desc": "Blockly erzeugt","unit": "","min": 0,"max": 10000,"def": 0,"read": true,"write": true}'), async () => {
});
// Timeouts
schedule("* * * * * *", async () => {
  setState('0_userdata.0.SmartPlugs.SmartPlug_EBike_Timeout' /* SmartPlug_EBike_Timeout */, (Math.min(Math.max(getState('0_userdata.0.SmartPlugs.SmartPlug_EBike_Timeout').val - 1, 0), 10000)));
});

// Steuerung
EBikeButtonAktiviert = false;
EBikePVAktiviert = false;
SmartPlugEBike = false;
schedule("* * * * * *", async () => {
  if (getState('0_userdata.0.SmartPlugs.SmarPlug_EBike').val) {
    if (!EBikeButtonAktiviert && getState('0_userdata.0.SmartPlugs.SmartPlug_EBike_Timeout').val == 0) {
      if (getState('0_userdata.0.ALIAS.EM24_HomeGrid_PV_Ueberschuss').val == 0) {
        SmartPlugEBike = false;
        EBikePVAktiviert = false;
      } else if (getState('0_userdata.0.ALIAS.EM24_HomeGrid_PV_Ueberschuss').val > 800) {
        SmartPlugEBike = true;
        EBikePVAktiviert = true;
      } else if (!EBikePVAktiviert && !SmartPlugEBike && getState('shelly.0.SHPLG-S#BC6DEB#1.Relay0.Switch').val) {
        EBikeButtonAktiviert = true;
        SmartPlugEBike = true;
      }
      if (getState('shelly.0.SHPLG-S#BC6DEB#1.Relay0.Switch').val != SmartPlugEBike) {
        setState('shelly.0.SHPLG-S#BC6DEB#1.Relay0.Switch' /* Schalter */, SmartPlugEBike);
        console.debug(('Smart Plug EBike geändert: ' + String(('' + SmartPlugEBike))));
        if (SmartPlugEBike == false) {
          setState('0_userdata.0.SmartPlugs.SmartPlug_EBike_Timeout' /* SmartPlug_EBike_Timeout */, 300);
        }
      }
    }
  } else {
    setState('shelly.0.SHPLG-S#BC6DEB#1.Relay0.Switch' /* Schalter */, false);
    SmartPlugEBike = false;
    EBikePVAktiviert = false;
  }
});


